    END_IF;
END_IF;

IF valid AND (segCount = 4) THEN
    ipValue := SHL(bytes[0], 24) OR SHL(bytes[1], 16) OR SHL(bytes[2], 8) OR bytes[3];
ELSE
    ipValue := 0;
END_IF;
```

